mapper.select:
SELECT SW.ShopCode, SW.WarehsCode, S.ShopName, SW.State, SW.Remark,
       SW.RegistId, SW.RegistName, SW.RegistDate, SW.ChangeId, SW.ChangeName, SW.ChangeDate
FROM shopwizard.tCmpShopWarehs SW
INNER JOIN shopwizard.tCmpShop S ON SW.ShopCode = S.ShopCode

    AND SW.ShopCode = #{pShopCode}
    AND SW.WarehsCode = #{pWarehsCode}

LIMIT #{pPageOffset}, #{pPageSize}

SELECT COUNT(*)
FROM shopwizard.tCmpShopWarehs SW
INNER JOIN shopwizard.tCmpShop S ON SW.ShopCode = S.ShopCode

    AND SW.ShopCode = #{pShopCode}
    AND SW.WarehsCode = #{pWarehsCode}

SELECT *
FROM shopwizard.tCmpShopWarehs
WHERE ShopCode = #{shopCode}
AND WarehsCode = #{warehsCode}

mapper.update:
UPDATE shopwizard.tCmpShopWarehs SET
    State = #{state}, Remark = #{remark},
    ChangeId = #{changeId}, ChangeName = #{changeName}, ChangeDate = NOW()
WHERE ShopCode = #{shopCode}
AND WarehsCode = #{warehsCode}

mapper.delete:
DELETE FROM shopwizard.tCmpShopWarehs
WHERE ShopCode = #{shopCode}
AND WarehsCode = #{warehsCode}
